import json
from pathlib import Path
s=Path('/root/.local/state/rust-full-migration-20261028-lu443ytp');w=s/'artifacts/receipt-parser-benchmark';d=w/'attempt4'
reports=[json.loads((w/'attempt1/benchmark/node-report.json').read_text()),json.loads((w/'attempt1/benchmark/native-report.json').read_text()),json.loads((d/'benchmark/native-report.json').read_text())]
rows=[]
for i in range(6):
 name=reports[0]['pools'][i]['name']; row={'name':name,'series':[]}
 for report in reports:
  p=report['pools'][i];assert name==p['name'];row['series'].append({k:p[k]/p['operations']/1000 for k in ['min','median','max']})
 rows.append(row)
(d/'comparison-data.json').write_text(json.dumps(rows,indent=2)+'\n')
html='''<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}body{margin:0;font:14px/1.45 var(--font-sans);color:var(--foreground)}p{margin:0 0 12px}.muted{color:var(--muted-foreground)}.small{font-size:12px}label{display:flex;align-items:center;gap:10px;margin:8px 0 18px}select{max-width:100%;padding:7px 10px;color:var(--foreground);background:var(--card);border:1px solid var(--border);border-radius:var(--radius);font:inherit}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;margin-bottom:12px}.legend span::before{content:"";display:inline-block;width:10px;height:10px;margin-right:5px;border-radius:2px;background:var(--c)}.chart{height:215px}svg{display:block;width:100%;height:215px}.summary{margin:6px 0 16px}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border-bottom:1px solid var(--border);padding:9px 5px;text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}th:first-child,td:first-child{text-align:left;padding-left:0}th{font-weight:600;color:var(--muted-foreground)}td:last-child{color:var(--success)}.notes{margin-top:14px;font-size:12px;color:var(--muted-foreground)}.notes p{margin-bottom:8px}code{font-size:11px;font-family:var(--font-mono)}
</style></head><body>
<p><strong>Receipt parser: measured time per operation</strong><br><span class="muted small">Prepared JSON → normalized receipt → ordered JSON and checksum. Lower is better.</span></p>
<label for="pool">Workload <select id="pool"></select></label>
<div class="legend"><span style="--c:var(--chart-1)">TypeScript</span><span style="--c:var(--chart-3)">Initial Rust</span><span style="--c:var(--chart-2)">Current Rust</span></div>
<div class="chart"><svg id="chart" role="img" aria-label="Selected workload median times and trial ranges"></svg></div>
<p id="summary" class="summary small"></p>
<div class="scroll"><table><thead><tr><th>Workload</th><th>TS µs</th><th>Initial Rust</th><th>Current Rust</th><th>Less time vs TS</th></tr></thead><tbody id="rows"></tbody></table></div>
<div class="notes"><p>Seven trials per workload; bars show medians, lines show the full trial range. All 192 expected wires and checksums matched. Original TypeScript timings were retained across the audited Rust source changes. Trials were run sequentially; no statistical significance claim.</p><p>The Rust changes reuse validated string and key spans, avoid decoding strings to test truthiness, and write receipt fields without an intermediate owned JSON tree.</p><p>This measures parser and JSON work only. It does not measure CPU, memory, queue or database performance, network time, or whole-application latency. No production deployment.</p></div>
<script>const data=__DATA__;const labels=['TypeScript','Initial Rust','Current Rust'];const colors=['var(--chart-1)','var(--chart-3)','var(--chart-2)'];const select=document.getElementById('pool');const fmt=n=>n.toFixed(3);data.forEach((d,i)=>{select.add(new Option(d.name,i));const r=document.createElement('tr');r.innerHTML='<td>'+d.name+'</td>'+d.series.map(s=>'<td>'+fmt(s.median)+'</td>').join('')+'<td>'+((1-d.series[2].median/d.series[0].median)*100).toFixed(1)+'%</td>';document.getElementById('rows').append(r)});function draw(){const d=data[Number(select.value)];const svg=document.getElementById('chart');const width=svg.clientWidth||360;const left=95,right=58,plot=Math.max(100,width-left-right);const max=Math.max(...d.series.map(s=>s.max))*1.06;const x=n=>left+n/max*plot;svg.setAttribute('viewBox','0 0 '+width+' 215');svg.innerHTML=d.series.map((s,i)=>{const y=25+i*62;return '<text x="0" y="'+(y+11)+'" fill="var(--foreground)" font-size="12">'+labels[i]+'</text><rect x="'+left+'" y="'+y+'" width="'+Math.max(1,x(s.median)-left)+'" height="18" rx="2" fill="'+colors[i]+'"/><line x1="'+x(s.min)+'" x2="'+x(s.max)+'" y1="'+(y+9)+'" y2="'+(y+9)+'" stroke="var(--foreground)"/><text x="'+left+'" y="'+(y+36)+'" fill="var(--muted-foreground)" font-size="11">'+fmt(s.median)+' µs · range '+fmt(s.min)+'–'+fmt(s.max)+'</text>'}).join('');document.getElementById('summary').textContent='Current Rust uses '+((1-d.series[2].median/d.series[0].median)*100).toFixed(1)+'% less median time than TypeScript for '+d.name+'.';}select.addEventListener('change',draw);new ResizeObserver(draw).observe(document.getElementById('chart'));draw();</script></body></html>'''
(d/'chart.html').write_text(html.replace('__DATA__',json.dumps(rows,separators=(',',':'))))
print('Prepared chart and six-pool comparison; awaiting final verification before rendering')
